const {withAppBuildGradle} = require('@expo/config-plugins');

/**
 * Sign release builds with the upload keystore instead of the debug one.
 *
 * `android/` is generated by `expo prebuild` and is gitignored, so editing
 * `app/build.gradle` by hand is not a fix — the next prebuild throws it away.
 * The template ships `signingConfig signingConfigs.debug` in the *release*
 * build type with a comment telling you to replace it, and a debug-signed
 * bundle is rejected by Play. This rewrites it on every prebuild.
 *
 * **No secret is stored here or anywhere in the repo.** The keystore path and
 * its three passwords are read from Gradle properties, which belong in
 * `~/.gradle/gradle.properties` — outside the project, so they cannot be
 * committed by accident:
 *
 *     DZDUINO_UPLOAD_STORE_FILE=/absolute/path/to/upload-keystore.jks
 *     DZDUINO_UPLOAD_STORE_PASSWORD=…
 *     DZDUINO_UPLOAD_KEY_ALIAS=upload
 *     DZDUINO_UPLOAD_KEY_PASSWORD=…
 *
 * When those properties are absent the build falls back to the debug key, so
 * a contributor with no keystore can still run a release build locally and
 * only a real upload needs the real key. That fallback is also the trap: a
 * bundle built without the properties is debug-signed and Play will refuse
 * it, which is why `verifyReleaseSigning` in the build steps checks the
 * signer before you upload.
 */
const SIGNING_CONFIGS = `    signingConfigs {
        release {
            if (project.hasProperty('DZDUINO_UPLOAD_STORE_FILE')) {
                storeFile file(DZDUINO_UPLOAD_STORE_FILE)
                storePassword DZDUINO_UPLOAD_STORE_PASSWORD
                keyAlias DZDUINO_UPLOAD_KEY_ALIAS
                keyPassword DZDUINO_UPLOAD_KEY_PASSWORD
            }
        }
        debug {`;

const RELEASE_SIGNING = `        release {
            signingConfig project.hasProperty('DZDUINO_UPLOAD_STORE_FILE')
                ? signingConfigs.release
                : signingConfigs.debug`;

module.exports = function withReleaseSigning(config) {
    return withAppBuildGradle(config, gradleConfig => {
        let contents = gradleConfig.modResults.contents;

        if (contents.includes('DZDUINO_UPLOAD_STORE_FILE')) {
            return gradleConfig;
        }

        const configsAnchor = '    signingConfigs {\n        debug {';
        const releaseAnchor =
            '        release {\n' +
            '            // Caution! In production, you need to generate your own keystore file.\n' +
            '            // see https://reactnative.dev/docs/signed-apk-android.\n' +
            '            signingConfig signingConfigs.debug';

        // A silent no-op here would ship a debug-signed bundle, so a template
        // that no longer matches has to stop the build rather than be skipped.
        if (!contents.includes(configsAnchor) || !contents.includes(releaseAnchor)) {
            throw new Error(
                'with-release-signing: app/build.gradle does not match the expected template. ' +
                    'Re-check the signingConfigs and release buildType blocks after the Expo upgrade.',
            );
        }

        contents = contents.replace(configsAnchor, SIGNING_CONFIGS);
        contents = contents.replace(releaseAnchor, RELEASE_SIGNING);

        gradleConfig.modResults.contents = contents;
        return gradleConfig;
    });
};
